const unmatchedAbilityTextAudit = new Map<string, { text: string; count: number; examples: Set<string> }>()
const missingAbilityTextExamples = new Set<string>()
let missingAbilityTextRecords = 0

type UnmatchedClassification = 'trainer-zone' | 'prize-zone' | 'stadium-zone' | 'tool-zone' | 'lost-zone' | 'individual-energy-state' | 'joke-or-nonbattle' | 'format-rule-equivalent' | 'review'

function classifyUnmatchedAbility(text: string): UnmatchedClassification {
  const value = normalize(text)
  if (/opponent can't have more than 3 benched pokemon/.test(value) && /discard benched pokemon until they have 3/.test(value)) return 'format-rule-equivalent'
  if (/\b(?:pokemon tool|tool card)\b/.test(value)) return 'tool-zone'
  if (/\b(?:trainer|supporter|item)\b/.test(value)) return 'trainer-zone'
  if (/\bprize cards?\b|\bprize card(?:s)? remaining\b|\bprize card(?:s)? left\b|\bpoints?\b/.test(value)) return 'prize-zone'
  if (/\bstadium\b/.test(value)) return 'stadium-zone'
  if (/\blost zone\b/.test(value)) return 'lost-zone'
  if (/\b(?:energy|energy card)s? attached\b|\battached (?:basic |special )?energy\b|\benergy attached\b/.test(value)) return 'individual-energy-state'
  if (/\bimakuni\b|hold this card and throw it/.test(value)) return 'joke-or-nonbattle'
  return 'review'
}

const unmatchedClassificationLabels: Record<UnmatchedClassification, string> = {
  'trainer-zone': 'Trainer, Supporter, or Item cards/zones',
  'prize-zone': 'Prize cards or points',
  'stadium-zone': 'Stadium cards and their in-play lifecycle',
  'tool-zone': 'Pokémon Tool cards and attachment lifecycle',
  'lost-zone': 'Lost Zone card zone',
  'individual-energy-state': 'Energy attached to specific Pokémon or attached Energy identity/counts',
  'joke-or-nonbattle': 'Joke/non-battle effect',
  'format-rule-equivalent': 'Already guaranteed by the battle format’s fixed three-slot Bench',
  review: 'Review: potentially implementable or approximable',
}

