function normalize(text: string): string {
  return text
    .replace(/<[^>]*>/g, ' ')
    .replace(/[’]/g, "'")
    .toLowerCase()
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .replace(/\s+/g, ' ')
    .trim()
}

